import {expect} from '@playwright/test';
export async function exercisePhotoAnnotations(page,{lang,photo,getPhoto,relabel,failNext,error,screenshot}){
  const t=(zh,en)=>lang==='en'?en:zh,card=()=>page.locator(`.photo-card[data-photo-id="${photo.id}"]`),viewer=page.locator('.photo-viewer');
  const open=async()=>{await card().locator('.photo-image').dblclick();await expect(viewer).toBeVisible();await viewer.getByRole('button',{name:t('照片信息','Photo information'),exact:true}).click();};
  await open();let editor=viewer.getByRole('textbox',{name:t('人工描述','Manual description'),exact:true});
  await expect(editor).toHaveValue('First AI');await editor.fill('我的说明 Manual');await editor.press('p');await viewer.getByRole('button',{name:t('保存描述','Save description'),exact:true}).click();await expect.poll(async()=>(await getPhoto()).user_description).toBe('我的说明 Manualp');expect((await getPhoto()).flag).toBe('picked');
  await editor.fill('');await viewer.getByRole('button',{name:t('保存描述','Save description'),exact:true}).click();await expect.poll(async()=>(await getPhoto()).user_description).toBe('');
  await viewer.locator('.tag-provenance summary').click();await viewer.getByRole('button',{name:t('转为人工标签：','Keep as manual tag: ')+'溪',exact:true}).click();await expect.poll(async()=>(await getPhoto()).tag_origins['溪']).toBe('user');await viewer.getByRole('button',{name:t('移除标签：','Remove tag: ')+'山',exact:true}).click();await expect.poll(async()=>(await getPhoto()).rejected_ai_tags).toEqual(['山']);
  await relabel();const p=await getPhoto();expect(p.description).toBe(null);expect(p.description_source).toBe('user');expect(p.tags).not.toContain('山');expect(p.tag_origins['溪']).toBe('user');expect(p.tag_origins['云']).toBe('ai');expect(p.tags).toContain('Manual');
  await page.keyboard.press('Escape');await page.reload();await open();editor=viewer.getByRole('textbox',{name:t('人工描述','Manual description'),exact:true});await expect(editor).toHaveValue('');
  await viewer.locator('.rejected-tags summary').click();await viewer.getByRole('button',{name:t('重新允许标签：','Allow tag again: ')+'山',exact:true}).click();await expect.poll(async()=>(await getPhoto()).tag_origins['山']).toBe('ai');
  await viewer.getByRole('button',{name:t('恢复使用 AI 描述','Use AI description'),exact:true}).click();await expect.poll(async()=>(await getPhoto()).description_source).toBe('ai');await expect(editor).toHaveValue('Second AI');
  if(failNext){await failNext();await editor.fill('unsaved draft');await viewer.getByRole('button',{name:t('保存描述','Save description'),exact:true}).click();await expect(page.locator('.toast')).toContainText(error);expect((await getPhoto()).user_description).toBe(null);await expect(editor).toHaveValue('unsaved draft');}
  await expect(viewer.locator('.photo-rating-source')).toHaveCount(1);await expect(viewer.locator('.photo-annotations')).toHaveCount(1);await viewer.locator('.tag-provenance summary').click();if(screenshot)await page.screenshot({path:screenshot,fullPage:true});await page.keyboard.press('Escape');
  await card().locator('.select-box').click();await page.getByRole('button',{name:t('批量编辑','Batch Edit'),exact:true}).click();let batch=page.getByRole('dialog');await batch.getByRole('combobox',{name:t('批量描述操作','Batch description action'),exact:true}).selectOption('clear');await batch.getByRole('button',{name:t('保存','Save'),exact:true}).click();await expect(batch).toHaveCount(0);await expect.poll(async()=>(await getPhoto()).user_description).toBe('');
  await card().locator('.select-box').click();await page.getByRole('button',{name:t('批量编辑','Batch Edit'),exact:true}).click();batch=page.getByRole('dialog');await batch.getByRole('combobox',{name:t('批量描述操作','Batch description action'),exact:true}).selectOption('ai');await batch.getByRole('button',{name:t('保存','Save'),exact:true}).click();await expect(batch).toHaveCount(0);await expect.poll(async()=>(await getPhoto()).description_source).toBe('ai');
}
